(()=>{
 'use strict';
 if(!/\/compatibility(?:\.html)?$/.test(location.pathname.replace(/\/+$/,'')))return;
 const ready=fn=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fn,{once:true}):fn();
 ready(()=>{
  if(document.querySelector('#fps-benchmark-lab'))return;
  const results=document.querySelector('#compat-results'),runtime=document.querySelector('#runtime-grid');
  if(!results||!runtime)return;

  const style=document.createElement('style');style.id='fps-benchmark-style';style.textContent=`
   .fps-lab{margin:34px 0 0;padding:28px 0;border-top:1px solid var(--compat-line,rgba(255,255,255,.11));border-bottom:1px solid var(--compat-line,rgba(255,255,255,.11))}.fps-lab-head{display:flex;justify-content:space-between;align-items:flex-start;gap:28px;margin-bottom:24px}.fps-lab-kicker{display:block;margin-bottom:8px;font-size:8px;letter-spacing:1.45px;color:var(--fg-777,#777)}.fps-lab h3{margin:0 0 9px;font-size:28px;letter-spacing:-.8px;font-weight:560}.fps-lab-head p{margin:0;max-width:650px;color:var(--fg-888,#888);font-size:10px;line-height:1.75}.fps-native{flex:none;padding:7px 10px;border:1px solid rgba(155,197,142,.22);color:var(--compat-ok,#9bc58e);font-size:7px;letter-spacing:.9px;text-transform:uppercase}.fps-preset-label{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:10px}.fps-preset-label strong{font-size:11px;font-weight:600}.fps-preset-label span{font-size:8px;color:var(--fg-666,#666)}.fps-presets{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.fps-preset{appearance:none;text-align:left;min-width:0;padding:14px;border:1px solid rgba(255,255,255,.10);border-radius:7px;background:rgba(255,255,255,.018);color:inherit;cursor:pointer;transition:border-color .18s,background .18s,transform .18s}.fps-preset:hover{border-color:rgba(255,255,255,.18)}.fps-preset[aria-pressed=true]{border-color:rgba(120,183,215,.42);background:rgba(120,183,215,.055)}.fps-preset b{display:block;margin-bottom:6px;font-size:10px;font-weight:600}.fps-preset small{display:block;color:var(--fg-6d6d6d,#6d6d6d);font-size:8px;line-height:1.5}.fps-preset em{display:inline-block;margin-top:9px;color:var(--compat-scan,#78b7d7);font-style:normal;font-size:7px;letter-spacing:.7px;text-transform:uppercase}.fps-preset-detail{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(240px,.75fr);gap:24px;margin:18px 0 0;padding:18px 0;border-top:1px solid rgba(255,255,255,.07);border-bottom:1px solid rgba(255,255,255,.07)}.fps-preset-detail h4{margin:0 0 7px;font-size:14px}.fps-preset-detail p{margin:0;color:var(--fg-7c7c7c,#7c7c7c);font-size:9px;line-height:1.75}.fps-setting-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 18px}.fps-setting-grid span{font-size:8px;color:var(--fg-676767,#676767)}.fps-setting-grid b{display:block;margin-top:3px;color:var(--fg-cdcdcd,#cdcdcd);font-size:10px;font-weight:500}.fps-run{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,.72fr);gap:28px;align-items:start;padding-top:24px}.fps-steps{display:grid;gap:0;margin:0;padding:0;list-style:none}.fps-steps li{display:grid;grid-template-columns:30px minmax(0,1fr);gap:10px;padding:11px 0;border-top:1px solid rgba(255,255,255,.065);color:var(--fg-929292,#929292);font-size:9px;line-height:1.65}.fps-steps li:first-child{border-top:0}.fps-steps li span{color:var(--fg-626262,#626262);font-size:8px}.fps-import{padding:18px;border:1px dashed rgba(255,255,255,.16);background:rgba(255,255,255,.012)}.fps-import label{display:block;font-size:10px;font-weight:600}.fps-import p{margin:7px 0 13px;color:var(--fg-6e6e6e,#6e6e6e);font-size:8px;line-height:1.65}.fps-import input{width:100%;font-size:9px;color:var(--fg-888,#888)}.fps-import input::file-selector-button{margin-right:9px;padding:7px 9px;border:1px solid rgba(255,255,255,.13);border-radius:5px;background:#1d1d1d;color:#ccc}.fps-error{margin:10px 0 0;color:var(--compat-bad,#e8837b);font-size:8px;line-height:1.6}.fps-output{margin-top:24px;padding-top:22px;border-top:1px solid rgba(255,255,255,.08)}.fps-output[hidden]{display:none!important}.fps-output-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:16px}.fps-output-head h4{margin:0;font-size:18px}.fps-output-head p{margin:5px 0 0;color:var(--fg-777,#777);font-size:9px}.fps-rating{font-size:10px;font-weight:600;color:var(--compat-ok,#9bc58e)}.fps-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.fps-metric{padding:15px;border:1px solid rgba(255,255,255,.09);border-radius:7px;background:rgba(255,255,255,.018)}.fps-metric span{display:block;color:var(--fg-676767,#676767);font-size:7px;letter-spacing:.8px;text-transform:uppercase}.fps-metric strong{display:block;margin-top:7px;font-size:22px;font-weight:550;letter-spacing:-.6px}.fps-recommend{margin-top:14px;padding:15px 0;border-top:1px solid rgba(255,255,255,.07);color:var(--fg-999,#999);font-size:9px;line-height:1.7}.fps-recommend b{color:var(--fg-d5d5d5,#d5d5d5)}
   @media(max-width:800px){.fps-presets{grid-template-columns:repeat(2,1fr)}.fps-preset:last-child{grid-column:1/-1}.fps-preset-detail,.fps-run{grid-template-columns:1fr}.fps-metrics{grid-template-columns:repeat(2,1fr)}}
   @media(max-width:480px){.fps-lab{padding-top:24px}.fps-lab-head{display:block}.fps-native{display:inline-block;margin-top:12px}.fps-presets{grid-template-columns:1fr}.fps-preset:last-child{grid-column:auto}.fps-setting-grid{grid-template-columns:1fr 1fr}.fps-metrics{grid-template-columns:1fr 1fr}.fps-metric strong{font-size:20px}}
   @media(prefers-reduced-motion:reduce){.fps-preset{transition:none}}
  `;document.head.append(style);

  const presets={
   saver:{name:'Battery Saver',caption:'Runs cool',copy:'Lowest-load starting point from the launcher preset family. Use it when heat, memory pressure, or sustained frame pacing matters more than image quality.'},
   balanced:{name:'Balanced',caption:'Recommended',copy:'The launcher provides device-specific Balanced variants including 540p/720p, shadows, reflections, and higher texture tiers as hardware headroom increases.'},
   performance:{name:'Performance',caption:'60 FPS family',copy:'The audited launcher includes Performance presets targeting 60 FPS, including a 720p variant on suitable hardware. Actual sustained FPS must be verified by the native benchmark.'},
   quality:{name:'Quality',caption:'Image quality',copy:'Quality presets use TAA/shadows and scale through 720p, 900p, 1080p and higher variants on stronger hardware classes.'},
   custom:{name:'Custom',caption:'Your settings',copy:'Benchmark the exact graphics configuration you currently use in the launcher.'}
  };
  const lab=document.createElement('section');lab.id='fps-benchmark-lab';lab.className='fps-lab';lab.innerHTML=`
   <div class="fps-lab-head"><div><span class="fps-lab-kicker">NATIVE GAME TEST</span><h3>FPS Benchmark</h3><p>This uses GTA V's own built-in benchmark output. The website analyzes real game FPS and frame-time data; it does not simulate gameplay in Safari.</p></div><span class="fps-native">Built into this port</span></div>
   <div class="fps-preset-label"><strong>Choose the preset you want to test</strong><span id="fps-auto-note"></span></div>
   <div class="fps-presets" role="group" aria-label="Benchmark graphics preset"></div>
   <div class="fps-preset-detail"><div><h4 id="fps-preset-title"></h4><p id="fps-preset-copy"></p></div><div class="fps-setting-grid" id="fps-setting-grid"></div></div>
   <div class="fps-run"><ol class="fps-steps"><li><span>01</span><div>Use the same preset in the GTA V launcher.</div></li><li><span>02</span><div>Tap <strong>Run the benchmark</strong>. The launcher starts GTA V with <code>-benchmark -benchmarkIterations=1</code>.</div></li><li><span>03</span><div>After it finishes, open the game's <strong>Benchmarks</strong> folder. The game writes <code>Benchmark-*.txt</code>; optional frame-time output can also be analyzed.</div></li><li><span>04</span><div>Import the benchmark text file here to calculate FPS, frame pacing, and the next preset recommendation.</div></li></ol><div class="fps-import"><label for="fps-benchmark-files">Import benchmark result</label><p>Benchmark-*.txt or FrameTimes-Pass*.txt. Processing stays in your browser.</p><input id="fps-benchmark-files" type="file" accept=".txt,.log,text/plain" multiple><div id="fps-benchmark-error" class="fps-error" role="alert" hidden></div></div></div>
   <div class="fps-output" id="fps-output" hidden><div class="fps-output-head"><div><h4>Benchmark result</h4><p id="fps-output-context"></p></div><span class="fps-rating" id="fps-rating"></span></div><div class="fps-metrics"><div class="fps-metric"><span>Average</span><strong id="fps-avg">—</strong></div><div class="fps-metric"><span>1% low</span><strong id="fps-low">—</strong></div><div class="fps-metric"><span>Minimum</span><strong id="fps-min">—</strong></div><div class="fps-metric"><span>30 FPS pacing</span><strong id="fps-30">—</strong></div></div><div class="fps-recommend" id="fps-recommend"></div></div>`;
  runtime.insertAdjacentElement('afterend',lab);

  const nav=document.querySelector('.result-nav');if(nav&&!nav.querySelector('a[href="#fps-benchmark-lab"]')){const a=document.createElement('a');a.href='#fps-benchmark-lab';a.textContent='FPS benchmark';a.style.display='inline-flex';a.style.marginRight='20px';nav.prepend(a)}

  const buttons=lab.querySelector('.fps-presets');let selected='balanced';
  for(const [id,p] of Object.entries(presets)){const b=document.createElement('button');b.type='button';b.className='fps-preset';b.dataset.preset=id;b.setAttribute('aria-pressed',String(id===selected));b.innerHTML=`<b>${p.name}</b><small>${p.caption}</small>${id==='balanced'?'<em>Starting point</em>':''}`;buttons.append(b)}
  const textFor=(label)=>{const cards=[...document.querySelectorAll('#hardware-grid .hardware-card')];const card=cards.find(c=>c.querySelector('.hardware-label')?.textContent.trim().toLowerCase()===label.toLowerCase());return card?.querySelector('h3')?.textContent.trim()||''};
  const hardware=()=>{const chip=textFor('System on chip'),ram=parseFloat(textFor('Installed RAM'))||0;const a=/A(\d+)/i.exec(chip);return {chip,ram,a:a?Number(a[1]):0}};
  function suggestedPreset(){const h=hardware();if(h.a===12||h.ram<4)return'saver';if(h.ram<=4.5||h.a===13||h.a===14)return'balanced';if(h.ram>=8&&h.a>=17)return'quality';if(h.ram>=6&&h.a>=15)return'performance';return'balanced'}
  function settingsFor(id){const h=hardware(),low=h.ram>0&&h.ram<=4.5;const texture=h.ram>=8?'Very High':h.ram>=6?'High':'Normal';let resolution='960×540',cap='30 FPS',aa='Off',metalfx='Auto / if supported';if(id==='saver'){resolution='854×480 / 960×540';cap='30 FPS'}if(id==='balanced'){resolution=h.a>=15&&h.ram>=6?'1280×720':'960×540';cap=h.a>=15?'40 FPS':'30 FPS'}if(id==='performance'){resolution=h.a>=17?'1280×720':'960×540';cap='60 FPS'}if(id==='quality'){resolution=h.a>=17&&h.ram>=8?'1600×900':'1280×720';cap='30–40 FPS';aa='TAA'}if(id==='custom'){resolution='Current launcher value';cap='Current launcher value';aa='Current launcher value';metalfx='Current launcher value'}return {Resolution:resolution,Textures:id==='custom'?'Current launcher value':texture,'Low-memory':id==='custom'?'Current launcher value':low?'On':'Auto',AA:aa,MetalFX:metalfx,'Frame cap':cap}}
  function select(id){selected=id;buttons.querySelectorAll('.fps-preset').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset===id)));const p=presets[id];lab.querySelector('#fps-preset-title').textContent=p.name;lab.querySelector('#fps-preset-copy').textContent=p.copy;const grid=lab.querySelector('#fps-setting-grid');grid.replaceChildren();for(const [k,v] of Object.entries(settingsFor(id))){const s=document.createElement('span');s.textContent=k;const b=document.createElement('b');b.textContent=v;s.append(b);grid.append(s)}}
  buttons.addEventListener('click',e=>{const b=e.target.closest('.fps-preset');if(b)select(b.dataset.preset)});
  const syncSuggestion=()=>{const id=suggestedPreset();lab.querySelector('#fps-auto-note').textContent='Suggested start: '+presets[id].name;if(!lab.dataset.touched)select(id)};
  buttons.addEventListener('click',()=>lab.dataset.touched='true',{once:true});select(selected);
  const observer=new MutationObserver(syncSuggestion);observer.observe(document.querySelector('#hardware-grid'),{childList:true,subtree:true});syncSuggestion();

  function parseSummary(text){const passes=[];let section='';for(const raw of text.split(/\r?\n/)){const line=raw.trim();if(/Frames Per Second/i.test(line)){section='fps';continue}if(/Frames under 16ms/i.test(line)){section='60';continue}if(/Frames under 33ms/i.test(line)){section='30';continue}let m;if(section==='fps'&&(m=/^Pass\s+(\d+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i.exec(line))){passes.push({pass:+m[1],min:+m[2],max:+m[3],avg:+m[4]});continue}if((section==='60'||section==='30')&&(m=/^Pass\s+(\d+):\s*(\d+)\/(\d+)\s+frames\s*\(([\d.]+)%\)/i.exec(line))){let p=passes.find(x=>x.pass===+m[1]);if(!p){p={pass:+m[1]};passes.push(p)}p[section==='60'?'under16':'under33']=+m[4]}}
   return passes.filter(p=>Number.isFinite(p.avg))}
  function parseFrameTimes(text){const vals=[];for(const raw of text.split(/\r?\n/)){const m=/^\s*\d+\s*[,\t ]\s*([\d.]+)\s*$/.exec(raw);if(m){const v=+m[1];if(v>0&&v<1000)vals.push(v)}}return vals}
  const percentile=(values,p)=>{if(!values.length)return null;const s=[...values].sort((a,b)=>a-b);return s[Math.min(s.length-1,Math.max(0,Math.ceil(p*s.length)-1))]};
  function analyze(files){let passes=[],times=[];for(const f of files){passes=passes.concat(parseSummary(f.text));times=times.concat(parseFrameTimes(f.text))}let avg=null,min=null,max=null,p30=null,low=null;if(passes.length){avg=passes.reduce((s,p)=>s+p.avg,0)/passes.length;min=Math.min(...passes.map(p=>p.min));max=Math.max(...passes.map(p=>p.max));const with30=passes.filter(p=>Number.isFinite(p.under33));if(with30.length)p30=with30.reduce((s,p)=>s+p.under33,0)/with30.length}if(times.length>10){const mean=times.reduce((a,b)=>a+b,0)/times.length;avg=1000/mean;const p99=percentile(times,.99);low=p99?1000/p99:null;min=1000/Math.max(...times);p30=times.filter(v=>v<=33.333).length/times.length*100}return {avg,min,max,p30,low,passes:passes.length,frames:times.length}}
  function rating(r){if(!Number.isFinite(r.avg))return['Not read','No recognized GTA V benchmark metrics were found.'];if(r.avg>=55&&(r.low===null||r.low>=40))return['Strong 60 FPS result','The tested preset has substantial 60 FPS headroom in this benchmark.'];if(r.avg>=45)return['Strong','The preset performs well, but sustained 60 FPS may vary by scene and temperature.'];if(r.avg>=30)return['Playable','The benchmark clears a 30 FPS average. Frame pacing and thermal behavior still matter.'];return['Heavy','This preset is too demanding for a stable 30 FPS target in the imported benchmark.']}
  function nextPreset(r){if(!Number.isFinite(r.avg))return selected;if(r.avg>=58&&(r.low===null||r.low>=45)){if(selected==='saver')return'balanced';if(selected==='balanced')return'performance';if(selected==='performance')return'quality';return selected}if(r.avg<30){if(selected==='quality'||selected==='performance')return'balanced';if(selected==='balanced')return'saver'}if(r.avg<45&&selected==='quality')return'balanced';return selected}
  const input=lab.querySelector('#fps-benchmark-files'),error=lab.querySelector('#fps-benchmark-error'),output=lab.querySelector('#fps-output');
  input.addEventListener('change',async()=>{error.hidden=true;output.hidden=true;const chosen=[...input.files];if(!chosen.length)return;try{const files=[];for(const file of chosen){if(file.size>2_000_000)throw Error('Use benchmark text files smaller than 2 MB.');files.push({name:file.name,text:await file.text()})}const r=analyze(files);if(!Number.isFinite(r.avg))throw Error('No GTA V benchmark FPS data found. Import Benchmark-*.txt or a FrameTimes-Pass*.txt file.');const [name,desc]=rating(r);lab.querySelector('#fps-rating').textContent=name;lab.querySelector('#fps-avg').textContent=r.avg.toFixed(1)+' FPS';lab.querySelector('#fps-low').textContent=Number.isFinite(r.low)?r.low.toFixed(1)+' FPS':'Summary only';lab.querySelector('#fps-min').textContent=Number.isFinite(r.min)?r.min.toFixed(1)+' FPS':'—';lab.querySelector('#fps-30').textContent=Number.isFinite(r.p30)?r.p30.toFixed(1)+'%':'—';lab.querySelector('#fps-output-context').textContent=`${presets[selected].name} · ${r.passes||0} summary pass${r.passes===1?'':'es'}${r.frames?` · ${r.frames} frame samples`:''}`;const next=nextPreset(r);lab.querySelector('#fps-recommend').innerHTML=`<b>${desc}</b><br>${next===selected?`Keep ${presets[selected].name} as the current target and compare a longer run if you want more confidence.`:`Next test: ${presets[next].name}. Re-run the native benchmark with that preset before treating it as stable.`}`;output.hidden=false;output.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}catch(e){error.textContent=e.message;error.hidden=false}});
 });
})();
